// The Error Trigger receives one item describing the failed execution:
//   { execution: { id, url, error, lastNodeExecuted, mode, retryOf },
//     workflow:  { id, name } }
// A workflow that fails before any node runs sends { trigger: { error } }.
const payload = $input.first().json;

const workflow = payload.workflow || {};
const execution = payload.execution || {};
const trigger = payload.trigger || {};
const error = execution.error || trigger.error || {};

const failedNode = error?.node?.name || execution.lastNodeExecuted || 'trigger / before first node';
const message = error.message || 'n8n supplied no error message';

// The item that was in flight when the node threw is the most useful thing in
// the whole alert, and the thing nobody thinks to include.
const context = error.context || {};
const excerpt = JSON.stringify(context.data ?? context ?? {}).slice(0, 900);

return [
  {
    json: {
      workflow_id: workflow.id || null,
      workflow_name: workflow.name || 'unknown',
      execution_id: execution.id || null,
      execution_url: execution.url || null,
      failed_node: failedNode,
      error_name: error.name || 'Error',
      error_message: message,
      error_description: error.description || null,
      error_stack: String(error.stack || '').slice(0, 2000) || null,
      execution_mode: execution.mode || null,
      retry_of: execution.retryOf || null,
      input_excerpt: excerpt,
      occurred_at: new Date().toISOString(),
      slack_payload: {
        text: 'n8n workflow failed: ' + (workflow.name || 'unknown'),
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: 'n8n workflow failed' } },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: '*Workflow*\n' + (workflow.name || 'unknown') },
              { type: 'mrkdwn', text: '*Failing node*\n' + failedNode },
              { type: 'mrkdwn', text: '*Execution*\n' + (execution.id || 'n/a') },
              { type: 'mrkdwn', text: '*Mode*\n' + (execution.mode || 'unknown') },
            ],
          },
          { type: 'section', text: { type: 'mrkdwn', text: '*Error*\n' + String(message).slice(0, 1500) } },
          { type: 'section', text: { type: 'mrkdwn', text: '*Item in flight*\n' + excerpt } },
          {
            type: 'context',
            elements: [
              {
                type: 'mrkdwn',
                text: execution.url
                  ? 'Open the execution: ' + execution.url
                  : 'Manual execution - no permalink',
              },
            ],
          },
        ],
      },
    },
  },
];
